using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class FaceSkill03Forward{
 public static object Run(){if(Application.isPlaying)throw new Exception("Stop play first");var report=new List<object>();foreach(string name in new[]{"Attack 05 - Skill_03","New Knight Combo Sequence Preview"}){var live=GameObject.Find(name);var root=UnityEngine.Object.Instantiate(live);root.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);try{var a=root.GetComponentInChildren<Animator>();a.enabled=false;var clip=a.runtimeAnimatorController.animationClips[0];string path=AssetDatabase.GetAssetPath(clip),backup=path.Replace(".anim","_BeforeForwardFacing.anim");if(AssetDatabase.LoadAssetAtPath<AnimationClip>(backup)==null)AssetDatabase.CopyAsset(path,backup);var source=AssetDatabase.LoadAssetAtPath<AnimationClip>(backup);var ts=a.GetComponentsInChildren<Transform>();var hip=ts.First(t=>t.name=="Hips");var left=ts.First(t=>t.name=="LeftUpperArm");var right=ts.First(t=>t.name=="RightUpperArm");string hp=AnimationUtility.CalculateTransformPath(hip,a.transform);bool combo=name.StartsWith("New Knight Combo");Func<float,bool> inside=t=>t<=16f/30f+.00001f||(combo&&t>=156f/30f-.00001f&&t<=172f/30f+.00001f);
 var bindings=Enumerable.Range(0,4).Select(c=>EditorCurveBinding.FloatCurve(hp,typeof(Transform),"m_LocalRotation."+"xyzw"[c])).ToArray();var curves=bindings.Select(b=>AnimationUtility.GetEditorCurve(source,b)).ToArray();var times=new SortedSet<float>(curves[0].keys.Select(k=>k.time));foreach(int start in combo?new[]{0,156}:new[]{0})for(int f=0;f<=128;f++)times.Add(start/30f+f/240f);var keys=Enumerable.Range(0,4).Select(_=>new List<Keyframe>()).ToArray();Quaternion previous=Quaternion.identity;bool first=true;float maxCorrection=0;
 foreach(float t in times){source.SampleAnimation(a.gameObject,t);Quaternion q=hip.localRotation;if(inside(t)){Vector3 facing=Vector3.Cross(right.position-left.position,Vector3.up).normalized;float yaw=Vector3.SignedAngle(Vector3.forward,facing,Vector3.up);maxCorrection=Mathf.Max(maxCorrection,Mathf.Abs(yaw));hip.rotation=Quaternion.AngleAxis(-yaw,Vector3.up)*hip.rotation;q=hip.localRotation;}if(!first&&Quaternion.Dot(previous,q)<0)q=new Quaternion(-q.x,-q.y,-q.z,-q.w);first=false;previous=q;for(int c=0;c<4;c++)keys[c].Add(new Keyframe(t,q[c]));}
 Undo.RecordObject(clip,"Face skill3 forward");for(int c=0;c<4;c++){var curve=new AnimationCurve(keys[c].ToArray());for(int k=0;k<curve.length;k++){AnimationUtility.SetKeyLeftTangentMode(curve,k,AnimationUtility.TangentMode.Linear);bool cut=combo&&new[]{16,51,93,155,172,218,303}.Any(f=>Mathf.Abs(curve.keys[k].time-f/30f)<.00001f);AnimationUtility.SetKeyRightTangentMode(curve,k,cut?AnimationUtility.TangentMode.Constant:AnimationUtility.TangentMode.Linear);}AnimationUtility.SetEditorCurve(clip,bindings[c],curve);}EditorUtility.SetDirty(clip);
 float error=0,outsideError=0;for(int f=0;f<=Mathf.RoundToInt(clip.length*120);f++){float t=f/120f;source.SampleAnimation(a.gameObject,t);var before=hip.localRotation;clip.SampleAnimation(a.gameObject,t);if(inside(t)){var facing=Vector3.Cross(right.position-left.position,Vector3.up).normalized;error=Mathf.Max(error,Mathf.Abs(Vector3.SignedAngle(Vector3.forward,facing,Vector3.up)));}else if(!(combo&&((t>16f/30f&&t<17f/30f)||(t>172f/30f&&t<173f/30f))))outsideError=Mathf.Max(outsideError,Quaternion.Angle(before,hip.localRotation));}
 clip.SampleAnimation(live.GetComponentInChildren<Animator>().gameObject,0);report.Add(new{name,maxCorrection,maxForwardError=error,otherSegmentRotationError=outsideError});}finally{UnityEngine.Object.DestroyImmediate(root);}}
 AssetDatabase.SaveAssets();var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return report;}
}

